<script setup>
/**
 * DOCTOL lockup — the official brand artwork, traced from the supplied
 * Illustrator PDF (شعار دكتول2) rather than typeset.
 *
 * The wordmark uses custom letterforms: the spray bottle is drawn *into* the
 * glyphs (the head of the Arabic "د" and the "D" of DOCTOL), so it can't be
 * rebuilt from a font — it has to ship as vector paths.
 *
 * Inlined instead of loaded as an <img> so the ink can recolour on dark
 * surfaces while the teal spray stays brand-coloured. The accessible name is
 * carried by the visually-hidden span, so the SVG itself stays aria-hidden.
 */
defineProps({
  size: { type: String, default: 'md', validator: (v) => ['sm', 'md', 'lg'].includes(v) },
  light: { type: Boolean, default: false },
})
</script>

